SELECT ot.PersonId, CONCAT('M01A','.',ot.TreatType) AS VarName, ABS(CHECKSUM(ot.DrugName)) % 100000 AS DpValue, ot.StartAt, ot.TreatId, ai.AtcName AS Caption FROM dbo.OngoingTreatment ot LEFT JOIN dbo.KBAtcIndex ai ON ai.AtcCode = ot.ATC WHERE ( PersonId IN (/*PIDS*/) ) AND ot.ATC COLLATE Latin1_General_CI_AI LIKE 'M01A%' COLLATE Latin1_General_CI_AI 